<script>(()=>{const wire=(id,button)=>{const m=document.getElementById(id),b=document.getElementById(button);if(!m||!b)return;const show=()=>{m.classList.add('is-open');m.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')},hide=()=>{m.classList.remove('is-open');m.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')};b.addEventListener('click',show);m.querySelectorAll('[data-close]').forEach(x=>x.addEventListener('click',hide));};wire('approveModal','openApprove');wire('rejectModal','openReject');})();</script>
